function bind(fn, result) {
  if (result.tag === 'Error') return result;
  return fn(result.value);
}

function half(n) {
  return n % 2 === 0 ? { tag: 'Ok', value: n / 2 } : { tag: 'Error', error: `${n} 不是偶數` };
}

const step1 = bind(half, { tag: 'Ok', value: 8 });
const step2 = bind(half, step1);
console.log(step2);

const stepA = bind(half, { tag: 'Ok', value: 7 });
const stepB = bind(half, stepA);
console.log(stepB);

