function bind(fn, result) {
  return result.tag === 'Error' ? result : fn(result.value);
}

let step3Called = false;

function step1(order) { return { tag: 'Ok', value: { ...order, validated: true } }; }
function step2() { return { tag: 'Error', error: '庫存不足' }; }
function step3(order) {
  step3Called = true;
  return { tag: 'Ok', value: { ...order, priced: true } };
}

let result = { tag: 'Ok', value: { id: 'A1' } };
result = bind(step1, result);
result = bind(step2, result);
result = bind(step3, result);

console.log(result);
console.log('step3 有沒有被呼叫：', step3Called);

